"""Plot the independently audited frozen feature-constraint diagnosis."""
import csv,hashlib,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def main():
    repo=Path(__file__).resolve().parents[1];root=repo/'results/motion_feature_constraint';status=json.loads((root/'status.json').read_text());job=status['job'];native=root/'native_completed';out=native/f'output/job_{job}'
    transfer=json.loads((native/'transfer_integrity.json').read_text());assert transfer['native_before_local_native_after_all_match']
    assert all(hashlib.sha256((native/k).read_bytes()).hexdigest()==v['sha256'] for k,v in transfer['files'].items())
    s=json.loads((out/'summary.json').read_text());audit=json.loads((out/'independent_audit.json').read_text());assert audit['status']=='PASS'
    assert json.loads((native/'execution_receipt.json').read_text())['status']=='COMPLETE_WITH_INDEPENDENT_AUDIT'
    with (out/'validation_feature_constraint.csv').open() as f:raw=list(csv.DictReader(f))
    cells={(c['seed'],c['horizon'],c['arm']):c for c in s['cells']}
    methods=['baseline','geometry_constraint','shuffled_geometry_control','oracle_position_constraint','oracle_full_basis'];labels=['Frozen baseline','Geometry constraint','Shuffled geometry','Oracle position','Oracle feature basis']
    fig,axes=plt.subplots(1,2,figsize=(11.7,4.6),layout='constrained')
    for ax,metric,title,meth in [(axes[0],'feature_mse','A  Complete visual-feature error',methods[:2]+methods[4:]),(axes[1],'position_mse','B  Position-readout error',methods[:2])]:
        width=.7/len(meth)
        for j,m in enumerate(meth):
            values=[];lo=[];hi=[]
            for h in (3,6):
                part=[r for r in raw if r['arm']==m and int(r['horizon'])==h];pairs=sorted({r['pair'] for r in part});x=np.array([np.mean([float(r[metric]) for r in part if r['pair']==p]) for p in pairs]);ix=np.random.default_rng(0).integers(0,96,(2000,96));a,b=np.percentile(x[ix].mean(1),[2.5,97.5]);values.append(x.mean());lo.append(x.mean()-a);hi.append(b-x.mean())
            bars=ax.bar([i+(j-(len(meth)-1)/2)*width for i in (0,1)],values,width,color=['.75','.15','white'][j],edgecolor='black',label=labels[methods.index(m)],yerr=[lo,hi],capsize=3)
            ax.bar_label(bars,fmt='%.4f',padding=20,fontsize=8)
        ax.set(xticks=[0,1],xticklabels=['3-step future','6-step future'],ylabel='MSE (lower is better)',title=title);ax.margins(y=.28);ax.legend(fontsize=8,loc='upper center',bbox_to_anchor=(.5,-.13),ncol=3)
    fig.suptitle('Does forcing the right coordinates also fix the visual prediction?\n96 validation pairs; no training, new encoding or predictor forward',fontsize=12)
    fig.savefig(root/'feature_constraint.png',dpi=180);plt.close(fig)
    lines=['# Frozen Motion feature-consistency check','', '## Purpose and fixed design','', 'The previous experiment showed that the original observed features contain useful motion information. This experiment asks a stricter question: can imposing that information on the complete visual prediction reduce actual feature error, rather than merely improve the position score?','', 'We reuse all 96 original validation base pairs, three frozen seeds and two horizons. No predictor was forwarded: the complete 5,120-dimensional predictions and actual target features come from the already audited CPU8336 witness file. Existing weights, normalization, position decoder and 128-dimensional output basis remain unchanged.','', 'One predeclared correction of strength 1 imposes the geometry-predicted coordinates with the smallest Euclidean feature change inside the original output basis. Its normal input uses only the allowed observed-frame geometry forecast. There is no parameter fitting, strength search, training, test inference, fresh9137 access or GPU consumption. This diagnoses a particular analytical correction, not every possible geometry-aware model.','', 'Subsequent [equal-capacity deletion validation](MOTION_FEATURE_DELETION.md) has completed. Despite this nominal improvement, arbitrary retained sets regress, so the unconditional correction is not adopted. The feasibility decision below records the StageA expansion decision before that experiment.', '', '## Controls and interpretation','', '- Frozen baseline: the original two-frame prediction.\n- Geometry constraint: the only normal candidate, using observed-input geometry.\n- Shuffled geometry: a fixed cross-pair negative control, not a usable candidate.\n- Oracle position: scoring truth supplies coordinates, isolated from the normal arm.\n- Oracle feature basis: scoring truth supplies the optimal complete feature change inside the frozen basis; it is an unattainable upper bound, not a model.','', 'Correcting a feature using the same position decoder will improve that decoder by construction. Only a reduction against the independently cached full target features can support a feature-prediction improvement.','', '![Feature versus position results](../results/motion_feature_constraint/feature_constraint.png)','', 'Bars show errors averaged over seeds and siblings within each base pair; error bars bootstrap 96 independent base pairs, 2,000 draws, seed 0, 95% percentile intervals. White bars use future scoring truth and are never valid model inputs.','', '| Method | Feature MSE, h3 | Feature MSE, h6 | Position MSE, h3 | Position MSE, h6 |','|---|---:|---:|---:|---:|']
    for m,label in zip(methods,labels):
        c3=cells['mean',3,m];c6=cells['mean',6,m];lines.append(f'|{label}|{c3["feature_mse"]:.8f}|{c6["feature_mse"]:.8f}|{c3["position_mse"]:.8f}|{c6["position_mse"]:.8f}|')
    lines+=['','## Incremental full-feature effect','', 'Positive values below mean lower full-feature error than the unmodified two-frame predictor. These are mean-over-seeds estimates, not independent additional datasets.','', '| Arm | h3 relative change [95%CI] | h6 relative change [95%CI] |','|---|---:|---:|']
    for m,label in zip(methods[1:],labels[1:]):
        x=[cells['mean',h,m]['feature_vs_baseline'] for h in (3,6)]
        lines.append('|'+label+'|'+'|'.join(f'{100*v["mean"]:.3f}% [{100*v["low"]:.3f}, {100*v["high"]:.3f}]' for v in x)+'|')
    lines+=['','## Expansion decision and unchanged acceptance','',f'The normal correction meets the original validation recent-only feature-benefit numerical rule in **{s["feature_numeric_checks"]}/8** cells and the task-position rule in **{s["position_numeric_checks"]}/8**. Its incremental feature benefit over the current prediction has a positive lower confidence bound in **{s["incremental_feature_positive_cells"]}/8** cells. Three seed estimates plus their mean, at two horizons, make these eight checks; they are not eight independent datasets.','', 'The predeclared resource screen requires all eight original numerical checks in both metrics plus positive incremental feature evidence before preparing a deletion experiment. This screen does not alter original acceptance or delete unfavorable data.','', f'Execution outcome: **{s["status"]}**. Deletion experiment executed: **{s["deletion_executed"]}**. Conditional deletion preparation eligible: **{s["conditional_deletion_eligible"]}**.','', 'Original full-test Motion results remain **35/51** prediction checks and **8/32** fixed-reference checks. No new full-test acceptance was performed. Gate remains its separately locked supported development candidate; fresh9137 remains closed and overall Phase1_GO is not established. A position-only correction cannot substitute for full-feature or deletion-cost reliability.','', '## Verification and resources','', f'All {s["rows"]:,} scalar rows were independently reconstructed using a different QR/SVD algorithm, rather than the primary Gram-matrix solver. Independent audit recomputed {audit["independent_intervals"]} paired intervals and every numerical flag. Vector/scalar maximum disagreement: {audit["independent_QR_SVD_vector_scalar_max_difference"]:.3g}; interval maximum disagreement: {audit["max_statistic_difference"]:.3g}. Original scalar replay maximum discrepancy: {s["baseline_replay_max_difference"]:.3g}. Compact artifacts passed native-before/local/native-after SHA checks.','', 'New GPU use is zero; cumulative charged GPU remains 12,723/28,800 seconds, with 16,077 seconds remaining. Primitive vectors and coefficient NPZ files remain HPC; compact numerical records and audit are retained locally. No GitHub update was made.','', '## Limits','', 'This is ordinary validation, not a new long-gap or distractor test and not independent confirmation. It does not prove that geometry is useless or identify a unique failing predictor branch. Any next repair must be specified from development evidence, preserve legitimate full-feature outputs and all original gates, and avoid tuning on confirmation data.']
    (repo/'docs/MOTION_FEATURE_CONSTRAINT.md').write_text('\n'.join(lines)+'\n');print('Wrote report and figure')

if __name__=='__main__':main()
